{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Disopyramide, the closest analogue (Morgan 0.333), has absolute oral bioavailability of 81.76% in volunteers despite a strongly basic ionizable amine and a 2-pyridyl/phenyl butylamine core, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Doxylamine, sharing the 2-pyridyl/phenyl and basic amine motif, showed 50% oral bioavailability in normal subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Imidafenacin, a heteroaryl/diphenyl butanamide analogue, has absolute oral bioavailability of 57.8% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Fexofenadine, a piperidine tertiary-alcohol analogue, has absolute oral bioavailability of 30% in human volunteers, supporting F ≥20% despite polar/zwitterionic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Bepotastine, a pyridyl/piperidine analogue, has >80% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ebastine, a piperidine butyl-chain analogue, achieves about 40% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Desethyloxybutynin enantiomers have 62-78% oral bioavailability in healthy adults, supporting high F for a basic tertiary-alcohol amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terfenadine has <2% oral bioavailability, but its extreme lipophilicity and CYP3A4 first-pass metabolism are not shared by the less lipophilic, pyridyl-containing query, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "R-Oxybutynin has ~6.7% oral bioavailability, but this ester undergoes extensive first-pass metabolism and has low structural similarity to the query, so it is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, led by the closest analogue disopyramide (F ~82%) and supported by doxylamine, imidafenacin, fexofenadine, bepotastine, ebastine, and desethyloxybutynin, indicates that the query's basic pyridyl/phenyl piperidine alcohol is likely to have oral bioavailability ≥20%. The low-F analogues terfenadine and oxybutynin owe their poor F to extensive first-pass metabolism and high lipophilicity not expected for this query. Physicochemical ionization is a liability but not decisive.",
  "evidence_gaps": [
    "No direct human pharmacokinetic or absolute oral bioavailability data for the query molecule.",
    "First-pass metabolism and CYP3A4/transporter susceptibility of the query are unknown.",
    "Morgan similarities to evidence molecules are moderate (0.24-0.33), limiting quantitative transferability.",
    "No permeability or efflux data are available for the query.",
    "The mCIPP analogue showed highly variable bioavailability spanning the threshold, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

